+        <div class="col"><div class="stats-card bg-light p-2 rounded text-center"><strong>@GetColumnTasks("Done").Count</strong><br /><small>Done</small></div></div>
+        <div class="col"><div class="stats-card bg-light p-2 rounded text-center text-danger"><strong>@_allTasks.Count(t => t.DueDate < DateTime.Today)</strong><br /><small>Overdue</small></div></div>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title..." @bind="_searchQuery" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="row g-3">
+        @foreach (var column in _columns)
+        {
+            var tasks = GetFilteredColumnTasks(column);
+            <div class="col-md-4">
+                <div class="card kanban-column">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@column</strong>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+                    <div class="card-body kanban-body">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card task-card mb-2">
+                                <div class="card-body p-2">
+                                    <h6 class="card-title mb-1">@task.Title</h6>
+                                    <p class="mb-1 text-muted small">@task.Assignee</p>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    </div>
+                                    <div class="d-flex justify-content-between mt-1">
+                                        @if (GetColumnIndex(column) > 0)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm" @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) - 1])" disabled="@_updating">← Move Left</button>
+                                        }
+                                        else
+                                        {
+                                            <span></span>
+                                        }
+                                        @if (GetColumnIndex(column) < _columns.Length - 1)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm" @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) + 1])" disabled="@_updating">Move Right →</button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @if (_addingToColumn == column)
+                        {
+                            <div class="card border-primary mb-2">
+                                <div class="card-body p-2">
+                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Title" @bind="_newTitle" />
+                                    <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee" @bind="_newAssignee" />
+                                    <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm mb-1" @bind="_newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-primary btn-sm flex-fill" @onclick="SaveNewTaskAsync" disabled="@_saving">Save</button>
+                                        <button class="btn btn-outline-secondary btn-sm flex-fill" @onclick="CancelAdd" disabled="@_saving">Cancel</button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+                    <div class="card-footer text-center">
+                        <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => StartAdd(column)" disabled="@(_addingToColumn is not null)">+ Add Task</button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private bool _updating;
+    private bool _saving;
+    private string? _error;
+    private string _searchQuery = string.Empty;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status) =>
+        _allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrWhiteSpace(_searchQuery)
+                || t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        try
+        {
+            _updating = true;
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _updating = false;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingToColumn = null;
+
+    private async Task SaveNewTaskAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null)
+            return;
+
+        try
+        {
+            _saving = true;
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+
+            // If the task was created in a column other than "To Do", update its status
+            if (_addingToColumn != "To Do")
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
+                created = created with { Status = _addingToColumn };
+            }
+
+            _allTasks.Add(created);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

